package com.bank.routing;

import java.util.logging.Logger;

public class FundsRouter {

    private static final Logger log = Logger.getLogger(FundsRouter.class.getName());

    public int minPathSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dp = new int[m][n];
        dp[0][0] = grid[0][0];
        for (int j = 1; j < n; j++) dp[0][j] = dp[0][j - 1] + grid[0][j]; // top row prefix
        for (int i = 1; i < m; i++) dp[i][0] = dp[i - 1][0] + grid[i][0]; // left col prefix
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = grid[i][j] + Math.min(dp[i - 1][j], dp[i][j - 1]); // cheaper entry
            }
        }
        int result = dp[m - 1][n - 1];
        log.info(() -> "minPathSum = " + result);
        return result;
    }
}
