package com.bank.routing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MinPathSumDemo {

    private static final Logger log = Logger.getLogger(MinPathSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Funds Router (Minimum Path Sum)");
        FundsRouter router = new FundsRouter();
        int[][] fees = {{1, 3, 1}, {1, 5, 1}, {4, 2, 1}};
        log.info("fees grid → " + router.minPathSum(fees)); // 7 (1→3→1→1→1)
    }
}
